def loans_to_batches(apps, schema_editor):
    """Each existing loan becomes a one-line batch that carries its borrower."""
    Loan = apps.get_model("labs", "EquipmentLoan")
    Batch = apps.get_model("labs", "EquipmentLoanBatch")
    for loan in Loan.objects.filter(batch__isnull=True).iterator():
        batch = Batch.objects.create(borrower_id=loan.borrower_id, created_by_id=loan.handed_over_by_id)
        Loan.objects.filter(pk=loan.pk).update(batch=batch)


